<script setup>
import {ref,computed,onMounted,defineAsyncComponent,watch} from 'vue'
import VoiceQueuePanel from './VoiceQueuePanel.vue'
import VoiceAudioPanel from './VoiceAudioPanel.vue'
import VoiceCallingPanel from './VoiceCallingPanel.vue'
const JourneyDashboard=defineAsyncComponent(()=>import('./JourneyDashboard.vue'))
const VoiceOperationsPanel=defineAsyncComponent(()=>import('./VoiceOperationsPanel.vue'))
import VoiceTwilioPanel from './VoiceTwilioPanel.vue'
import VoiceFollowupSettings from './VoiceFollowupSettings.vue'
import VoiceJourneyCanvas from './VoiceJourneyCanvas.vue'
import WhatsAppPanel from './WhatsAppPanel.vue'
import {Phone,Plus,RefreshCw,FileText,Upload,Play,Pause,Settings2,X,ShieldCheck,ArrowRight} from 'lucide-vue-next'
const props=defineProps({focusId:Number,section:{type:String,default:'flow'},initialSub:{type:String,default:''}});const emit=defineEmits(['catalog','journey','changed','lists','section','back'])
const canvas=ref(null),pendingLeave=ref(null)
const sectionTitles={flow:'Fluxo da cadência',create:'Nova cadência de voz',queues:'Supervisão',channels:'Canais',reports:'Relatórios',tests:'Testes'}
const sectionTabs={flow:[],create:[],queues:[['operations','Filas e regras'],['calling','Chamadas avulsas']],channels:[['whatsapp','WhatsApp'],['twilio','Twilio e telefonia'],['origins','Números de saída']],reports:[['dashboard','Dashboard por jornada'],['operations','Chamadas e tabulação'],['cadence','WhatsApp e histórico']],tests:[['agent','Simular atendimento'],['queues','Simular filas'],['audio','Áudio no navegador'],['contacts','Contatos de teste'],['imports','Importação XLSX'],['reference','Documento e roteiro']]}
const tabs=computed(()=>sectionTabs[props.section]||[])
function requestLeave(fn){if(busy.value){pendingLeave.value=fn;return}if(dialog.value&&!window.confirm('Fechar o formulário e descartar as alterações não salvas?'))return;if(canvas.value)canvas.value.requestLeave(fn);else fn()}
defineExpose({requestLeave})

const journeyId=ref(props.focusId||null),operationsTab=ref(props.initialSub==='policies'?'policies':props.section==='queues'?'live':props.section==='tests'?'lists':'reports')
function openJourney(c){journeyId.value=c.id;tab.value='journey';emit('journey',c.id)}
async function journeySaved(j){const i=data.value.journeys.findIndex(old=>old.id===j.id);if(i>=0)data.value.journeys[i]=j;await run(refresh)}
function journeyNavigate(section){if(section==='lists'){emit('lists');return}if(section==='whatsapp')emit('section','channels','whatsapp');else if(section==='reports')tab.value='dashboard';else emit('section','queues',section)}
watch(()=>props.focusId,id=>{if(id){journeyId.value=id;tab.value='journey'}})
const data=ref(null),tab=ref(['flow','create'].includes(props.section)?'journey':props.section==='reports'?(['cadence','operations'].includes(props.initialSub)?props.initialSub:'dashboard'):props.section==='queues'?(props.initialSub==='calling'?'calling':'operations'):(tabs.value.some(([k])=>k===props.initialSub)?props.initialSub:tabs.value[0]?.[0]||'journey')),busy=ref(false),error=ref(''),notice=ref(''),dialog=ref(null),form=ref({}),selectedCampaign=ref(''),selectedContact=ref(''),outcome=ref('no_answer'),qualification=ref('interested'),callbackAt=ref(''),importResult=ref(null),csv=ref(null)
watch(busy,value=>{if(!value&&pendingLeave.value){const fn=pendingLeave.value;pendingLeave.value=null;requestLeave(fn)}})
const importForm=ref({source:'',consent:false,consent_evidence:'',name_column:'nome',phone_column:'telefone',delimiter:';'})
const names={draft:'Rascunho',testing:'Em simulação',paused:'Pausada',completed:'Concluída',cancelled:'Cancelada',ringing:'Em chamada simulada',finished:'Finalizada',expired:'Expirada',pending:'Aguardando teste',blocked:'Impedida',simulated:'Simulada',answered:'Atendida',no_answer:'Não atendeu',busy:'Ocupado',machine:'Caixa postal',invalid:'Número inválido',rejected:'Rejeitada',interested:'Interessado',callback:'Retorno agendado',not_interested:'Sem interesse',opt_out:'Pediu interrupção'}
const contact=id=>data.value?.contacts.find(c=>c.id===id)
const campaign=id=>data.value?.campaigns.find(c=>c.id===id)
const journeyOverview=computed(()=>data.value?.journeys?.find(j=>j.id===Number(journeyId.value)))
const campaignChoice=computed(()=>campaign(Number(selectedCampaign.value)))
const campaignContacts=computed(()=>data.value?.contacts.filter(c=>campaignChoice.value?.contact_ids.includes(c.id))||[])
const currentCall=computed(()=>data.value?.attempts.find(c=>c.user_id===data.value.user_id&&c.status==='ringing'&&new Date(c.expires_at.replace(' ','T')+'Z')>new Date()))
const references=(kind,channel=null)=>data.value?.references.filter(r=>r.kind===kind&&(!channel||r.channel===channel))||[]
const date=s=>s?new Date(/[Z+]|T.*-\d\d:\d\d$/.test(s)?s:s.replace(' ','T')+'Z').toLocaleString('pt-BR'):'—'
async function api(path,method='GET',body){const multipart=body instanceof FormData;const r=await fetch('/api/voice'+path,{method,headers:{Accept:'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content,...(!multipart?{'Content-Type':'application/json'}:{})},...(body?{body:multipart?body:JSON.stringify(body)}:{})});const d=await r.json();if(!r.ok)throw new Error(d.errors?Object.values(d.errors).flat().join(' · '):[d.message,...(d.issues||[])].join(' '));return d}
async function refresh(){data.value=await api('');emit('changed')}
async function run(fn){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
onMounted(()=>run(async()=>{await refresh();if(props.section==='create')newCampaign()}))
function newCampaign(c=null){form.value=c?JSON.parse(JSON.stringify(c)):{name:'',contact_ids:[],settings:{mode:'preview',crm_campaign_id:'',segment_id:'',business_number:'',number_mode:'single',whatsapp_number:'',whatsapp_sender_id:null,timezone:'America/Sao_Paulo',days:[1,2,3,4,5],start_time:'08:00',end_time:'18:00',max_attempts:3,retry_minutes:60,concurrency:1,script:'',whatsapp_enabled:false,whatsapp_after:3,whatsapp_delay:10,whatsapp_template_id:'',whatsapp_delivery:'automatic',whatsapp_text:'',whatsapp_real_template_id:null,whatsapp_variables:{}}};form.value.settings.number_mode ||= 'single';form.value.settings.whatsapp_delivery ||= 'simulation';form.value.settings.whatsapp_variables ||= {};form.value.settings.whatsapp_real_template_id ||= null;dialog.value='campaign'}
function newContact(){form.value={name:'',phone:'',source:'',crm_contact_id:'',consent:false,consent_evidence:''};dialog.value='contact'}
async function save(){await run(async()=>{if(dialog.value==='campaign'){const created=!form.value.id;const saved=await api('/campaigns'+(form.value.id?'/'+form.value.id:''),form.value.id?'PUT':'POST',{name:form.value.name,revision:form.value.revision,contact_ids:form.value.contact_ids,settings:{...form.value.settings,whatsapp_number:form.value.settings.number_mode==='single'?form.value.settings.business_number:form.value.settings.whatsapp_number}});if(created)journeyId.value=saved.id;}else{const result=await api('/contacts','POST',form.value);notice.value=result.duplicate?'Contato já cadastrado. Autorização e exclusões anteriores preservadas.':'Contato cadastrado.'}dialog.value=null;await refresh();if(props.section==='create'&&journeyId.value)openJourney(campaign(journeyId.value))})}
async function transition(c,status){await run(async()=>{await api('/campaigns/'+c.id+'/status','POST',{status});await refresh();notice.value=status==='testing'?(c.settings.whatsapp_delivery==='automatic'?'Cadência habilitada. A sequência só começa quando iniciada em Filas e atendimento, com atendente disponível.':'Simulação iniciada. Abra Atendimento para testar as chamadas.'):'Status atualizado.'})}
async function start(next=false){await run(async()=>{await api('/calls','POST',{campaign_id:Number(selectedCampaign.value),contact_id:next?null:Number(selectedContact.value),idempotency_key:crypto.randomUUID()});await refresh();notice.value='Chamada simulada aberta. Escolha abaixo o resultado do teste.'})}
async function finish(){await run(async()=>{await api('/calls/'+currentCall.value.id+'/finish','POST',{outcome:outcome.value,...(outcome.value==='answered'?{qualification:qualification.value,...(qualification.value==='callback'?{callback_at:new Date(callbackAt.value).toISOString()}:{})}:{})});await refresh();notice.value='Resultado registrado. Consulte Cadência para verificar a próxima ação.'})}
async function stop(c,type){await run(async()=>{await api('/contacts/'+c.id+'/stop','POST',{type});await refresh();notice.value=type==='opt_out'?'Contato excluído. Ações pendentes canceladas em todas as campanhas de teste.':'Atendimento registrado. Cadência interrompida.'})}
async function importCsv(commit){await run(async()=>{const f=new FormData();f.append('file',csv.value);for(const[k,v]of Object.entries(importForm.value))f.append(k,typeof v==='boolean'?(v?'1':'0'):v);f.append('commit',commit?'1':'0');importResult.value=await api('/imports','POST',f);if(commit){await refresh();notice.value='Importação concluída; duplicados preservados e linhas inválidas ignoradas.'}})}
function changedImport(){importResult.value=null}
</script>

<template>
 <section class="voice-lab" :class="{'is-builder':tab==='journey'}">
  <div v-if="!['journey','dashboard','whatsapp'].includes(tab)" class="section-heading"><div><span class="eyebrow">CADÊNCIAS</span><h1>{{sectionTitles[section]}}</h1><p>{{section==='channels'?'Conecte seus números de voz e WhatsApp. Escolha o remetente em cada cadência.':section==='queues'?'Configure as filas, os atendentes e os limites de abordagem.':section==='reports'?'Acompanhe voz e WhatsApp. Os resultados das automações também estão na aba Relatórios de cada cadência.':'Valide os caminhos e consulte o histórico antes de iniciar sua operação.'}}</p></div><button class="secondary" :disabled="busy" @click="run(refresh)"><RefreshCw :size="16"/> Atualizar</button></div>
  <div v-if="section==='tests'" class="lab-banner"><ShieldCheck :size="22"/><div><strong>Laboratório de testes</strong><p>Simule resultados e verifique o áudio. Chamadas reais ficam em Minha operação; números e templates ficam em Canais.</p></div><a href="/api/voice/reference" target="_blank" rel="noopener"><FileText :size="16"/> Documento balizador</a></div>
  <div v-if="error" role="alert" class="error">{{error}}</div><div v-if="notice" role="status" class="lab-notice">{{notice}}</div>
  <nav v-if="tabs.length>1" class="lab-tabs" :aria-label="'Seções de '+sectionTitles[section]"><button v-for="[key,label] in tabs" :key="key" :class="{selected:tab===key}" @click="tab=key">{{label}}</button></nav>
  <p v-if="!data">Carregando laboratório…</p>
  <template v-else>
   <div v-if="section==='tests'" class="lab-stats"><article><small>Contatos de teste</small><strong>{{data.totals.contacts}}</strong></article><article><small>Tentativas simuladas</small><strong>{{data.totals.attempts}}</strong></article><article><small>Passos simulados</small><strong>{{data.totals.simulated_actions}}</strong></article><article><small>Mensagens aceitas pelo provedor</small><strong>{{data.totals.real_messages}}</strong></article></div>
   <template v-if="tab==='journey'"><div class="cadence-editor-actions"><button class="secondary" @click="requestLeave(()=>emit('back'))"><ArrowRight :size="15" style="transform:rotate(180deg)"/> Voltar para cadências</button><button v-if="journeyOverview" class="secondary" @click="requestLeave(()=>tab='dashboard')">Ver dashboard</button><template v-if="journeyOverview&&data.can_manage_journeys"><button v-if="['draft','paused'].includes(journeyOverview.status)" class="secondary" :disabled="busy" @click="requestLeave(()=>transition(campaign(journeyOverview.id),'testing'))"><Play :size="15"/> Habilitar cadência</button><button v-if="journeyOverview.status==='testing'" class="secondary" :disabled="busy" @click="transition(campaign(journeyOverview.id),'paused')"><Pause :size="15"/> Pausar cadência</button></template><button v-if="section==='create'" class="primary" @click="newCampaign()">Criar cadência de voz</button></div><VoiceJourneyCanvas ref="canvas" v-if="journeyOverview" :key="journeyOverview.id" :journey="journeyOverview" :campaign="campaign(journeyOverview.id)" :contacts="data.contacts" :lists="data.journey_lists||[]" :senders="data.whatsapp_senders||[]" :templates="data.whatsapp_templates||[]" :qr-templates="data.whatsapp_qr_templates||[]" :references="data.references||[]" :can-manage="data.can_manage_journeys" @configure="newCampaign(campaign(journeyOverview.id))" @navigate="journeyNavigate" @saved="journeySaved"/><p v-else>Selecione uma campanha para explorar as etapas e suas configurações.</p></template>
   <template v-if="tab==='campaigns'">
    <div class="lab-heading"><h2>Campanhas de voz</h2><button class="primary" @click="newCampaign()"><Plus :size="16"/> Nova campanha de voz</button></div>
    <div v-if="!data.campaigns.length" class="table-card empty-state"><Phone :size="36"/><h2>Comece por uma conversa.</h2><p>Cadastre contatos de teste e configure sua primeira campanha.<br>As referências do CRM podem ser vinculadas agora.</p><button class="primary" @click="tab='contacts'">Adicionar contatos <ArrowRight :size="16"/></button></div>
    <div class="campaign-grid"><article v-for="c in data.campaigns" :key="c.id" class="table-card campaign-card"><div class="lab-heading"><span class="journey-symbol"><Phone :size="22"/></span><span class="status" :class="c.status==='testing'?'active':'paused'">{{c.status==='testing'&&c.settings.whatsapp_delivery==='automatic'?'Habilitada para chamadas reais':names[c.status]}}</span></div><h2>{{c.name}}</h2><p>{{c.settings.mode==='preview'?'Preview · escolha do contato':'Progressivo · próximo contato elegível'}}</p><dl><div><dt>Público de teste</dt><dd>{{c.contact_ids.length}} contatos</dd></div><div><dt>Limites</dt><dd>{{c.settings.max_attempts}} tentativas · {{c.settings.concurrency}} simultânea(s)</dd></div><div><dt>Horário</dt><dd>{{c.settings.start_time}}–{{c.settings.end_time}}</dd></div><div><dt>WhatsApp</dt><dd>{{c.settings.whatsapp_enabled?'Após '+c.settings.whatsapp_after+' não atendimentos':'Sem passo configurado'}}</dd></div></dl><div class="lab-actions"><button class="secondary" @click="openJourney(c)">Ver jornada <ArrowRight :size="15"/></button><button v-if="['draft','paused'].includes(c.status)" class="secondary" @click="newCampaign(c)"><Settings2 :size="15"/> Configurar</button><button v-if="['draft','paused'].includes(c.status)" class="primary" :disabled="busy" @click="transition(c,'testing')"><Play :size="15"/> {{c.settings.whatsapp_delivery==='automatic'?'Habilitar campanha':'Simular'}}</button><button v-if="c.status==='testing'" class="secondary" :disabled="busy" @click="transition(c,'paused')"><Pause :size="15"/> Pausar</button><button v-if="c.status==='testing'" class="primary" @click="selectedCampaign=c.id;selectedContact='';tab='agent'">Abrir atendimento</button></div></article></div>
   </template>
   <template v-if="tab==='contacts'">
    <div class="lab-heading"><h2>Contatos do laboratório</h2><button class="primary" @click="newContact"><Plus :size="16"/> Novo contato de teste</button></div>
    <details class="table-card lab-import"><summary><Upload :size="17"/> Importar CSV com prévia</summary><p>Até 500 linhas por arquivo. Informe origem e autorização válidas para os contatos importados. Duplicados não alteram registros existentes.</p><form @submit.prevent="importCsv(false)" @input="changedImport" @change="changedImport"><div class="lab-grid"><label>Arquivo CSV<input type="file" accept=".csv,text/csv" required @change="csv=$event.target.files[0]"></label><label>Origem dos contatos<input v-model="importForm.source" required maxlength="300" placeholder="Ex.: base fictícia de homologação"></label><label>Coluna de nome<input v-model="importForm.name_column" required></label><label>Coluna de telefone<input v-model="importForm.phone_column" required></label><label>Separador<select aria-label="Separador" v-model="importForm.delimiter"><option value=";">Ponto e vírgula (;)</option><option value=",">Vírgula (,)</option></select></label></div><label class="check-label"><input type="checkbox" v-model="importForm.consent">Há autorização registrada para comunicações da empresa.</label><label v-if="importForm.consent">Evidência da autorização do lote<textarea v-model="importForm.consent_evidence" required maxlength="2000"/></label><button class="secondary" :disabled="busy||!csv">Conferir prévia</button></form><div v-if="importResult" class="import-preview"><strong>{{importResult.valid}} válidos · {{importResult.duplicates}} duplicados · {{importResult.invalid}} inválidos · {{importResult.created}} importados</strong><ul><li v-for="e in importResult.errors" :key="e.line">Linha {{e.line}}: {{e.message}}</li></ul><table><thead><tr><th>Prévia · até 10 contatos</th><th>Telefone normalizado</th></tr></thead><tbody><tr v-for="c in importResult.preview" :key="c.phone"><td>{{c.name}}</td><td>{{c.phone}}</td></tr></tbody></table><button v-if="!importResult.committed&&importResult.valid" class="primary" :disabled="busy" @click="importCsv(true)">Importar linhas válidas</button></div></details>
    <div class="table-card lab-table"><table><thead><tr><th>Contato</th><th>Origem</th><th>Autorização</th><th>Situação</th><th>Ações de teste</th></tr></thead><tbody><tr v-for="c in data.contacts" :key="c.id"><td><strong>{{c.name}}</strong><small>{{c.phone}}</small></td><td>{{c.source}}</td><td>{{c.consent?'Registrada':'Ausente'}}</td><td>{{c.suppressed_at?'Excluído':c.replied_at?'Em atendimento':'Disponível'}}</td><td><div class="lab-actions"><button class="secondary" :disabled="busy||!!c.suppressed_at||!!c.replied_at" @click="stop(c,'reply')">Simular resposta</button><button class="secondary" :disabled="busy||!!c.suppressed_at" @click="stop(c,'opt_out')">Registrar interrupção</button></div></td></tr></tbody></table><p v-if="!data.contacts.length" class="empty-small">Adicione contatos fictícios para testar o fluxo.</p></div><small class="lab-muted">Exibindo até 500 contatos. O cadastro do CRM será conectado em etapa posterior.</small>
   </template>
   <template v-if="tab==='agent'">
    <div class="agent-grid"><section class="table-card lab-box"><span class="eyebrow">ÁREA DO ATENDENTE</span><h2>Próxima conversa</h2><label>Campanha em simulação<select aria-label="Campanha em simulação" v-model="selectedCampaign" @change="selectedContact=''" :disabled="!!currentCall"><option value="">Selecione a campanha</option><option v-for="c in data.campaigns.filter(c=>c.status==='testing')" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>Contato para preview<select aria-label="Contato para preview" v-model="selectedContact" :disabled="!!currentCall"><option value="">Selecione o contato</option><option v-for="c in campaignContacts" :key="c.id" :value="c.id">{{c.name}} · {{c.phone}}</option></select></label><div class="lab-actions"><button class="primary" :disabled="busy||!selectedContact||!!currentCall" @click="start(false)"><Phone :size="16"/> Simular ligação</button><button v-if="campaignChoice?.settings.mode==='progressive'" class="secondary" :disabled="busy||!!currentCall" @click="start(true)">Próximo elegível</button></div><h3>Roteiro da campanha</h3><p class="script">{{campaignChoice?.settings.script||'Selecione uma campanha ou cadastre um roteiro nas configurações.'}}</p><p v-if="campaignChoice" class="lab-muted">Intervalo mínimo: {{campaignChoice.settings.retry_minutes}} minutos. Respostas e exclusões impedem novas tentativas.</p></section>
    <section class="table-card lab-box"><span class="eyebrow">RESULTADO DO TESTE</span><template v-if="currentCall"><h2>{{contact(currentCall.contact_id)?.name}}</h2><p>{{contact(currentCall.contact_id)?.phone}} · {{campaign(currentCall.campaign_id)?.name}}</p><span class="status active">Chamada simulada · nenhum áudio transmitido</span><form @submit.prevent="finish"><label>Resultado da chamada<select aria-label="Resultado da chamada" v-model="outcome"><option v-for="key in ['no_answer','answered','busy','machine','invalid','rejected']" :key="key" :value="key">{{names[key]}}</option></select></label><label v-if="outcome==='answered'">Qualificação<select aria-label="Qualificação" v-model="qualification"><option v-for="key in ['interested','callback','not_interested','opt_out']" :key="key" :value="key">{{names[key]}}</option></select></label><label v-if="outcome==='answered'&&qualification==='callback'">Data do retorno<input v-model="callbackAt" type="datetime-local" required></label><button class="primary" :disabled="busy">Concluir tentativa simulada</button></form></template><template v-else><h2>Pronto para testar.</h2><p>Inicie uma chamada ao lado e escolha o resultado. O sistema avaliará a cadência e registrará o histórico.</p></template></section></div>
   </template>
   <template v-if="tab==='cadence'">
    <h2>Próximos passos da cadência</h2><p class="lab-muted">“Simular vencimento” avalia as condições atuais no horário previsto. Não espera o relógio nem envia mensagens.</p><div class="table-card lab-table"><table><thead><tr><th>Contato / campanha</th><th>Previsto para</th><th>Estado</th><th>Resultado</th><th></th></tr></thead><tbody><tr v-for="a in data.actions" :key="a.id"><td>{{contact(a.contact_id)?.name||'#'+a.contact_id}}<small>{{campaign(a.campaign_id)?.name}}</small></td><td>{{date(a.due_at)}}</td><td>{{names[a.status]}}</td><td>{{a.reason||'Revalidar autorização, resposta e horário antes de continuar.'}}</td><td><button v-if="a.status==='pending'" class="secondary" :disabled="busy" @click="run(async()=>{await api('/actions/'+a.id+'/simulate','POST');await refresh()})">Simular vencimento</button></td></tr></tbody></table><p v-if="!data.actions.length" class="empty-small">Os passos aparecerão quando as regras de não atendimento forem alcançadas.</p></div>
    <h2>WhatsApp após chamadas reais</h2><div class="table-card lab-table"><table><thead><tr><th>Contato</th><th>Campanha</th><th>Estado / motivo</th><th>Previsto para</th><th></th></tr></thead><tbody><tr v-for="f in data.followups" :key="f.id"><td>{{contact(f.contact_id)?.name}}</td><td>{{campaign(f.campaign_id)?.name}}</td><td>{{({pending:'Aguardando horário',dispatching:'Processando',blocked:'Impedido',cancelled:'Cancelado',unknown:'Sem confirmação',queued:'Na fila do provedor',sent:'Enviado',delivered:'Entregue',read:'Lido',failed:'Falhou'})[f.status]||f.status}}<small>{{f.reason}}</small></td><td>{{date(f.due_at)}}</td><td><button v-if="f.status==='blocked'&&!f.message_id" class="secondary" :disabled="busy" @click="run(async()=>{await api('/whatsapp/followups/'+f.id+'/retry','POST',{});await refresh()})">Reavaliar após corrigir</button></td></tr></tbody></table><p v-if="!data.followups?.length" class="empty-small">Nenhum limiar atingido em chamadas reais.</p></div>
    <h2>Histórico de tentativas simuladas</h2><div class="table-card lab-table"><table><thead><tr><th>Contato</th><th>Campanha</th><th>Estado</th><th>Resultado técnico</th><th>Qualificação</th><th>Início</th></tr></thead><tbody><tr v-for="a in data.attempts" :key="a.id"><td>{{contact(a.contact_id)?.name||'#'+a.contact_id}}</td><td>{{campaign(a.campaign_id)?.name||'#'+a.campaign_id}}</td><td>{{names[a.status]}}</td><td>{{names[a.outcome]||'—'}}</td><td>{{names[a.qualification]||'—'}}</td><td>{{date(a.created_at)}}</td></tr></tbody></table><p v-if="!data.attempts.length" class="empty-small">Nenhuma tentativa registrada.</p></div><small class="lab-muted">Últimas 200 tentativas e 200 ações. Resultados de simulação não representam conversões reais.</small>
    <details class="table-card lab-box"><summary>Auditoria do laboratório · últimos 100 eventos</summary><table><thead><tr><th>Evento</th><th>Registro</th><th>Quando</th></tr></thead><tbody><tr v-for="a in data.audit" :key="a.id"><td>{{a.event}}</td><td>{{a.subject_id}}</td><td>{{date(a.created_at)}}</td></tr></tbody></table></details>
   </template>
   <VoiceAudioPanel v-if="tab==='audio'"/>
   <VoiceCallingPanel v-if="tab==='calling'"/>
   <JourneyDashboard v-if="tab==='dashboard'" :campaign-id="section==='flow'?journeyId:undefined" :campaigns="data.campaigns" @back="tab='journey'"/>
   <VoiceOperationsPanel v-if="['operations','origins','imports'].includes(tab)" :key="tab" :initial-tab="tab==='origins'?'origins':tab==='imports'?'lists':operationsTab" :allowed-tabs="section==='queues'?['live','policies']:section==='reports'?['reports']:tab==='origins'?['origins']:['lists']"/>
   <VoiceQueuePanel v-if="tab==='queues'"/>
   <VoiceTwilioPanel v-if="tab==='twilio'"/>
   <WhatsAppPanel v-if="tab==='whatsapp'" @changed="refresh"/>
   <template v-if="tab==='reference'">
    <div class="agent-grid"><article class="table-card lab-box"><span class="eyebrow">DIRETRIZ DO PRODUTO</span><h2>Números flexíveis. Histórico contínuo.</h2><p>A ligação usa a rede telefônica convencional. Cada campanha pode usar um número único para voz e WhatsApp ou números separados, conforme a disponibilidade dos fornecedores.</p><p>O fornecedor ainda precisa comprovar essa combinação. Informar um número na campanha não significa que ele está conectado.</p><a class="secondary" href="/api/voice/reference" target="_blank" rel="noopener"><FileText :size="16"/> Abrir PDF de referência</a><h3>Preparação do CRM</h3><p>Campanhas, segmentos e templates podem usar referências já cadastradas no MA. Selecionar um segmento ainda não importa seus contatos.</p><button class="secondary" @click="emit('catalog')">Gerenciar referências do CRM</button></article><article class="table-card lab-box"><span class="eyebrow">ANTES DAS CHAMADAS REAIS</span><h2>Conexões pendentes</h2><ul class="readiness"><li v-for="p in data.activation_pending" :key="p"><span class="status paused">Pendente</span>{{p}}</li></ul></article></div>
    <div class="table-card lab-box"><h2>Roteiro de evolução</h2><ol class="roadmap"><li><strong>Laboratório disponível</strong><p>Configuração, CSV, autorização, preview/progressivo simulado, exclusões e histórico.</p></li><li><strong>Voz e WhatsApp reais</strong><p>Prova do número, operadora, áudio no navegador, API oficial, callbacks e reconciliação.</p></li><li><strong>Atendimento e IA de texto</strong><p>Caixa de entrada, responsável, conhecimento publicado, transferência para humano, agenda, CRM e consumo.</p></li><li><strong>Expansão após homologação</strong><p>IA de voz, supervisão e discagem preditiva.</p></li></ol><p class="lab-muted">O laboratório possui escopo por workspace. A aplicação MA completa ainda precisa de isolamento e permissões para receber empresas externas.</p></div>
   </template>
  </template>
  <div v-if="dialog" class="modal-backdrop" @click.self="dialog=null"><form class="modal voice-modal" @submit.prevent="save"><div class="modal-title"><h2>{{dialog==='campaign'?(form.id?'Configuração da cadência':'Nova cadência de voz'):'Novo contato de teste'}}</h2><button type="button" aria-label="Fechar formulário de voz" @click="dialog=null"><X :size="22"/></button></div><label>Nome<input v-model="form.name" required maxlength="160"></label>
   <template v-if="dialog==='campaign'"><div class="lab-grid"><label>Modo de discagem<select aria-label="Modo de discagem" v-model="form.settings.mode"><option value="preview">Preview · escolher contato</option><option value="progressive">Progressivo · próximo elegível</option></select></label><label>Número de voz<input v-model="form.settings.business_number" @input="form.settings.whatsapp_sender_id=null" placeholder="+5511999990000"><small>Apenas preparação; conexão pendente.</small></label><label>Campanha do CRM<select aria-label="Campanha do CRM" v-model="form.settings.crm_campaign_id"><option value="">Sem vínculo por enquanto</option><option v-for="r in references('campaign')" :key="r.id" :value="r.external_id">{{r.name}}</option></select></label><label>Segmento do CRM<select aria-label="Segmento do CRM" v-model="form.settings.segment_id"><option value="">Sem vínculo por enquanto</option><option v-for="r in references('segment')" :key="r.id" :value="r.external_id">{{r.name}}</option></select></label></div><fieldset><legend>Números da campanha</legend><label class="check-label"><input type="checkbox" :checked="form.settings.number_mode==='single'" @change="form.settings.number_mode=$event.target.checked?'single':'separate';form.settings.whatsapp_sender_id=null">Usar um único número para voz e WhatsApp</label><label v-if="form.settings.number_mode==='separate'">Número de WhatsApp<input v-model="form.settings.whatsapp_number" @input="form.settings.whatsapp_sender_id=null" placeholder="+5511999990000"></label><p v-else class="lab-muted">WhatsApp: {{form.settings.business_number||'informe o número de voz'}}. A disponibilidade nos dois serviços precisa ser confirmada.</p><label>Remetente WhatsApp cadastrado<select aria-label="Remetente WhatsApp cadastrado" v-model="form.settings.whatsapp_sender_id"><option :value="null">Vincular depois</option><option v-for="sender in (data.whatsapp_senders||[]).filter(s=>s.number===(form.settings.number_mode==='single'?form.settings.business_number:form.settings.whatsapp_number))" :key="sender.id" :value="sender.id">{{sender.label}} · {{sender.provider==='qr'?'QR Code':'Twilio API'}} · {{sender.status}}</option></select></label><small>Cadastre o número em Cadências → Canais → WhatsApp. Salvar esta opção não conecta a operadora nem ativa disparos automáticos.</small></fieldset><p class="lab-muted">As referências não importam contatos automaticamente. Escolha abaixo o público deste teste.</p><label>Público de teste</label><div class="lab-contact-picker"><label v-for="c in data.contacts" :key="c.id" class="check-label"><input type="checkbox" v-model="form.contact_ids" :value="c.id">{{c.name}} · {{c.phone}}{{c.suppressed_at?' · excluído':''}}</label><p v-if="!data.contacts.length">Cadastre contatos na seção Contatos e CSV.</p></div><div class="lab-grid"><label>Fuso horário<select aria-label="Fuso horário" v-model="form.settings.timezone"><option>America/Sao_Paulo</option><option>America/Manaus</option><option>America/Rio_Branco</option><option>UTC</option></select></label><label>Chamadas simultâneas<input type="number" v-model.number="form.settings.concurrency" min="1" max="2" required></label><label>Início do horário<input type="time" v-model="form.settings.start_time" required></label><label>Fim do horário<input type="time" v-model="form.settings.end_time" required></label></div><fieldset><legend>Dias permitidos</legend><div class="lab-days"><label v-for="(day,i) in ['Seg','Ter','Qua','Qui','Sex','Sáb','Dom']" :key="day" class="check-label"><input type="checkbox" v-model="form.settings.days" :value="i+1">{{day}}</label></div></fieldset><div class="lab-grid"><label>Máximo de tentativas<input type="number" v-model.number="form.settings.max_attempts" min="1" max="20" required></label><label>Intervalo entre tentativas (min)<input type="number" v-model.number="form.settings.retry_minutes" min="1" max="10080" required></label></div><label>Roteiro do atendente<textarea v-model="form.settings.script" rows="3" maxlength="4000" placeholder="Objetivo da conversa e perguntas de qualificação"/></label><VoiceFollowupSettings :settings="form.settings" :contacts="data.contacts" :campaign-name="form.name" :senders="data.whatsapp_senders" :templates="data.whatsapp_templates" :qr-templates="data.whatsapp_qr_templates||[]" :references="references('template','whatsapp')"/></template>
   <template v-else><label>Telefone<input v-model="form.phone" required maxlength="80" placeholder="+55 11 99999-0000"></label><label>Origem do contato<input v-model="form.source" required maxlength="300" placeholder="Ex.: contato fictício de homologação"></label><label>ID do contato no CRM · opcional<input v-model="form.crm_contact_id" maxlength="160"></label><label class="check-label"><input type="checkbox" v-model="form.consent">Há autorização para comunicações da empresa.</label><label v-if="form.consent">Evidência da autorização<textarea v-model="form.consent_evidence" required maxlength="2000" placeholder="Origem, finalidade e referência do registro"/></label></template>
   <div v-if="error" role="alert" class="error">{{error}}</div><div class="modal-actions"><button type="button" class="secondary" @click="dialog=null">Cancelar</button><button class="primary" :disabled="busy">Salvar {{dialog==='campaign'?'cadência':'contato'}}</button></div></form></div>
 </section>
</template>

